import {validateBlockGeometry} from './building-block-geometry.js?v=arc-landmark-1';
import {validateSurfaceDetails} from './building-surface-details.js?v=arc-landmark-1';
import {validateFloorPaint} from './building-floor-paint.js?v=arc-landmark-1';
import {validateBuildingVoxels,drawBuildingVoxels} from './building-voxels.js?v=arc-landmark-1';
import {parseBuildingSlot,validateBuildingFootprint,sameBuildingFootprint,tileBuildingFootprint,projectBuildingPoint} from './building-footprints.js?v=arc-landmark-1';
import {validateBuildingMaterials} from './building-materials.js?v=arc-landmark-1';
import {validateBuildingBlocks,drawBuildingBlocks} from './building-blocks.js?v=arc-landmark-1';
import {REPLACEABLE_STYLES,baseZonedSprite,canReplaceBuilding,buildingStyleKey} from './building-art.js?v=arc-landmark-1';
export function defaultBuildingDesign(key=2){const {source,footprint}=parseBuildingSlot(key);return{name:REPLACEABLE_STYLES[source]?.level===1?'My neighborhood building':'My building',floors:[0,2,6,12][REPLACEABLE_STYLES[source]?.level||3],width:8,depth:8,roof:'step',facade:'#b6c4bd',windows:'#3c6b79',accent:'#dab572',...(footprint.width!==1||footprint.height!==1?{footprint}:{})};}
// Original procedural artwork for larger lots; style swaps select a matching
// footprint model, never enlarge a legacy single-tile image.
export function defaultLotDesign(source,footprint){const d=defaultBuildingDesign(`${source}@${footprint.width}x${footprint.height}`),style=REPLACEABLE_STYLES[source];d.name=style.name;if(style.group==='commercial')Object.assign(d,{facade:'#9bbdc2',windows:'#28576c',accent:'#d5d9d2',roof:'flat'});if(style.group==='industrial'){Object.assign(d,{facade:source>=54?'#b8c9b7':'#a78972',windows:'#47616a',accent:'#c5b07e',floors:style.level+1,roof:'flat'});d.blocks=Array.from({length:100},(_,i)=>{const x=i%10,y=Math.floor(i/10);return x<1||x>8||y<1||y>8?0:x<3&&y<3?d.floors+4:y===5&&x<6?0:d.floors;});}return d;}
export function validateBuildingDesign(v){if(!v||typeof v.name!=='string'||!v.name.trim()||v.name.length>40||/[\x00-\x1f]/.test(v.name)||!Number.isInteger(v.floors)||v.floors<1||v.floors>24||!Number.isInteger(v.width)||v.width<6||v.width>10||!Number.isInteger(v.depth)||v.depth<6||v.depth>10||!['flat','step','spire'].includes(v.roof)||!['facade','windows','accent'].every(k=>typeof v[k]==='string'&&/^#[0-9a-f]{6}$/i.test(v[k])))throw Error('Choose a name, 1–24 floors, dimensions 6–10, a roof style and valid colors.');const result=Object.fromEntries(['name','floors','width','depth','roof','facade','windows','accent'].map(k=>[k,k==='name'?v[k].trim():v[k]]));if(v.footprint!==undefined)result.footprint=validateBuildingFootprint(v.footprint);if(v.voxels!==undefined){if(v.blocks!==undefined)throw Error('Choose either a height layout or independent layers.');result.voxels=validateBuildingVoxels(v.voxels);}if(v.blocks!==undefined)result.blocks=validateBuildingBlocks(v.blocks);if(v.materials!==undefined){if(!result.blocks&&!result.voxels)throw Error('Surface paint needs a block layout.');result.materials=validateBuildingMaterials(v.materials);}if(v.surfacePaint!==undefined){if(!result.blocks&&!result.voxels)throw Error('Floor paint needs a block layout.');result.surfacePaint=validateFloorPaint(v.surfacePaint);}if(v.surfaceDetails!==undefined){if(!result.blocks&&!result.voxels)throw Error('Building details need a block layout.');result.surfaceDetails=validateSurfaceDetails(v.surfaceDetails);}if(v.blockGeometry!==undefined)result.blockGeometry=validateBlockGeometry(v.blockGeometry,result.voxels);return result;}
export function validateBuildingDesigns(v){if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).length>Object.keys(REPLACEABLE_STYLES).length*16)throw Error('Invalid custom building library.');const result={};for(const [key,design]of Object.entries(v)){const slot=parseBuildingSlot(key);if(!Object.hasOwn(REPLACEABLE_STYLES,slot.source))throw Error('Invalid custom building slot.');result[key]=validateBuildingDesign(design);if(!sameBuildingFootprint(result[key].footprint,slot.footprint))throw Error('The building file must match the selected tile footprint.');}return result;}
export function designForTile(city,tile){if(!canReplaceBuilding(tile))return null;return city.buildingDesigns?.[buildingStyleKey(city,tile)]||null;}
export function applyBuildingDesign(city,source,design){if(!Object.hasOwn(REPLACEABLE_STYLES,parseBuildingSlot(source).source))throw Error('Choose a building style.');city.buildingDesigns=validateBuildingDesigns({...city.buildingDesigns,[source]:design});}
export function exportBuildingDesign(design){return JSON.stringify({format:'SIMS3000-building',version:design.blockGeometry?8:design.surfaceDetails?7:design.surfacePaint?6:design.voxels?5:design.footprint?4:design.materials?3:design.blocks?2:1,design:validateBuildingDesign(design)},null,design.blockGeometry?0:2);}
export function importBuildingDesign(text){if(typeof text!=='string'||text.length>32768)throw Error('Building files must be smaller than 32 KB.');let file;try{file=JSON.parse(text);}catch{throw Error('This is not a valid building file.');}if(file?.format!=='SIMS3000-building'||![1,2,3,4,5,6,7,8].includes(file.version)||file.version<8&&file.design?.blockGeometry!==undefined||file.version===8&&file.design?.blockGeometry===undefined||file.version<7&&file.design?.surfaceDetails!==undefined||file.version===7&&file.design?.surfaceDetails===undefined||file.version<6&&file.design?.surfacePaint!==undefined||file.version===6&&file.design?.surfacePaint===undefined||file.version<5&&file.design?.voxels!==undefined||file.version===5&&file.design?.voxels===undefined||file.version<4&&((file.version>=2)!==(file.design?.blocks!==undefined)||(file.version===3)!==(file.design?.materials!==undefined)||file.design?.footprint!==undefined)||file.version===4&&file.design?.footprint===undefined)throw Error('Choose a SIMS3000 building file.');return validateBuildingDesign(file.design);}
const tint=(hex,factor)=>'#'+hex.slice(1).match(/../g).map(v=>Math.min(255,Math.round(parseInt(v,16)*factor)).toString(16).padStart(2,'0')).join('');
// Model coordinates project into a fixed transparent canvas; cached city drawings remain cheap.
export function drawBuildingDesign(ctx,d,rotation=0){
 const unit=64,rot=((rotation%4)+4)%4,turn=(x,y)=>rot===0?[x,y]:rot===1?[-y,x]:rot===2?[-x,-y]:[y,-x];
 const project=p=>projectBuildingPoint(p,rotation,d.footprint);
 const polygon=(points,color)=>{ctx.beginPath();points.map(project).forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=color;ctx.fill();};
 function box(w,dep,z,height,color,windows=false,floors=1){const corners=[[-w/2,-dep/2],[w/2,-dep/2],[w/2,dep/2],[-w/2,dep/2]],visible=[[1,2],[0,1],[0,3],[2,3]][rot];
  for(const side of visible){const a=corners[side],b=corners[(side+1)%4];polygon([[...a,z],[...b,z],[...b,z+height],[...a,z+height]],tint(color,side%2?.72:.9));
   if(windows)for(let floor=0;floor<floors;floor++)for(let column=0;column<4;column++){const left=(column+.2)/4,right=(column+.73)/4,low=z+(floor+.23)*height/floors,high=z+(floor+.7)*height/floors,point=(f,h)=>[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,h];polygon([point(left,low),point(right,low),point(right,high),point(left,high)],(floor*7+column*3+side)%9===0?d.accent:d.windows);}}
  polygon(corners.map(a=>[...a,z+height]),tint(color,1.08));
 }
 polygon([[-.5,-.5,0],[.5,-.5,0],[.5,.5,0],[-.5,.5,0]],'#69847c');
 if(d.voxels){drawBuildingVoxels(ctx,d,rotation);return;}
 if(d.blocks){drawBuildingBlocks(ctx,d,rotation);return;}
 const w=d.width*.085,dep=d.depth*.085,h=d.floors*.14;box(w+.08,dep+.08,0,.12,d.accent);if(d.roof==='step'){const lower=Math.ceil(d.floors*.65);box(w,dep,.12,lower*.14,d.facade,true,lower);box(w*.7,dep*.7,.12+lower*.14,(d.floors-lower)*.14,d.facade,true,d.floors-lower);}else box(w,dep,.12,h,d.facade,true,d.floors);
 box(w*.3,dep*.3,h+.12,.12,d.accent);if(d.roof==='spire'){const p=project([0,0,h+.25]),q=project([0,0,h+.8]);ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.strokeStyle=d.accent;ctx.lineWidth=3;ctx.stroke();}
}
export function buildingDesignCanvas(design,rotation=0){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=384;drawBuildingDesign(canvas.getContext('2d'),design,rotation);return canvas;}
const sprites=new Map();
export function drawDesignedBuilding(renderer,tile,design,opacity=1){const key=JSON.stringify(design)+renderer.rotation;let canvas=sprites.get(key);if(!canvas){canvas=buildingDesignCanvas(design,renderer.rotation);if(sprites.size>=64)sprites.delete(sprites.keys().next().value);sprites.set(key,canvas);}const city=renderer.getCity(),footprint=tileBuildingFootprint(city,tile),lot=city.buildingLots?.get(tile.lotRoot),p=renderer.project(lot?lot.x+(lot.width-1)/2:tile.x,lot?lot.y+(lot.height-1)/2:tile.y),scale=renderer.unit*Math.max(footprint.width,footprint.height)/64,c=renderer.ctx;c.save();c.globalAlpha=opacity;c.drawImage(canvas,p.x-128*scale,p.y+renderer.unit/2-346*scale,256*scale,384*scale);c.restore();}
